import { useEffect, useMemo, useState } from "react";
import { supabase } from "./lib/supabase";
import { LayoutDashboard, ShoppingBag, Landmark, CreditCard, Receipt, BarChart3, Settings, LogOut, Menu, X, Plus, RefreshCw, Search, Download, CheckCircle2, AlertCircle, Upload, Database, Utensils, ClipboardCheck } from "lucide-react";

const modules=[
  ["dashboard","Dashboard",LayoutDashboard],["vendas","Vendas",ShoppingBag],["recebimentos","Recebimentos",Receipt],["bancos","Bancos / Extratos",Landmark],
  ["cartoes","Cartões",CreditCard],["caixa","Caixa / Fluxo de caixa",Landmark],["contas","Contas a pagar",Receipt],["compras","Compras / Matéria-prima",ShoppingBag],["despesas","Despesas",Receipt],["cardapio","Cardápio",Utensils],["conciliacao","Conciliação",ClipboardCheck],["dados","Dados / Importações / Backup",Database],["relatorios","Relatórios",BarChart3],["configuracoes","Configurações",Settings]
];
const money=v=>new Intl.NumberFormat("pt-BR",{style:"currency",currency:"BRL"}).format(Number(v||0));
const dateBR=v=>v?new Date(v+"T00:00:00").toLocaleDateString("pt-BR"):"—";
const today=()=>new Date().toISOString().slice(0,10);
const monthStart=()=>new Date(new Date().getFullYear(),new Date().getMonth(),1).toISOString().slice(0,10);

async function seedUser(user){
  const defaults=[
    {name:"TON",institution:"TON",account_type:"bank"},
    {name:"iFood Pago",institution:"iFood",account_type:"bank"}
  ];
  const cats=[
    ["Venda","Receita"],["iFood","Receita"],["BeeFood","Receita"],["99Food","Receita"],["PIX","Receita"],["Outros recebimentos","Receita"],
    ["Matéria-prima","Despesas"],["Fornecedor","Despesas"],["Aluguel","Despesas"],["Energia","Despesas"],["Água","Despesas"],["Internet","Despesas"],["Funcionários","Despesas"],["Impostos","Despesas"],["Taxas","Despesas"],["Manutenção","Despesas"],["Outras despesas","Despesas"],
    ["Transferência entre contas","Outros"],["Aporte","Outros"],["Retirada","Outros"],["Ajuste","Outros"],["Empréstimo","Outros"]
  ];
  const chans=["Direto","iFood","BeeFood","99Food"];
  const [{data:banks},{data:existingCats},{data:existingChans}]=await Promise.all([
    supabase.from("bank_accounts").select("id").eq("user_id",user.id).limit(1),
    supabase.from("categories").select("id").eq("user_id",user.id).limit(1),
    supabase.from("channels").select("id").eq("user_id",user.id).limit(1)
  ]);
  if(!banks?.length) await supabase.from("bank_accounts").insert(defaults.map(x=>({...x,user_id:user.id})));
  if(!existingCats?.length) await supabase.from("categories").insert(cats.map(([name,classification])=>({user_id:user.id,name,classification})));
  if(!existingChans?.length) await supabase.from("channels").insert(chans.map(name=>({user_id:user.id,name})));

  const menu = [
    {category:"Pizzas Tradicionais", items:[
      ["A MODA",[45.99,55.99,65.99,80.99]],["CALABRESA",[44.99,54.99,64.99,79.99]],["FRANGO C/ CATUPIRY",[45.99,55.99,65.99,80.99]],["PORTUGUESA",[44.99,54.99,64.99,79.99]],["TOSCANA",[44.99,54.99,64.99,79.99]],["LOMBINHO",[44.99,54.99,64.99,79.99]],["4 QUEIJOS",[44.99,54.99,64.99,79.99]],["MARGUERITA",[44.99,54.99,64.99,79.99]],["VEGETARIANA",[44.99,54.99,64.99,79.99]]
    ]},
    {category:"Pizzas Especiais", items:[
      ["FRANGO ESPECIAL",[45.99,55.99,65.99,80.99]],["CALABRESA ESPECIAL",[44.99,54.99,64.99,79.99]],["BACON ESPECIAL",[44.99,54.99,64.99,79.99]],["RAVENNA",[44.99,54.99,64.99,79.99]],["NÁPOLES",[44.99,54.99,64.99,79.99]],["4 CARNES",[45.99,55.99,65.99,80.99]],["LOMBINHO C/ CHEDDAR",[44.99,54.99,64.99,79.99]],["SAINTROPEZ",[44.99,54.99,64.99,79.99]],["PRESUNTO ESPECIAL",[44.99,54.99,64.99,79.99]],["VENEZA",[44.99,54.99,64.99,79.99]],["CATUPIRY ESPECIAL",[44.99,54.99,64.99,79.99]],["VEGETARIANA ESPECIAL",[44.99,54.99,64.99,79.99]]
    ]},
    {category:"Bebidas", items:[
      ["REFRIGERANTE 1 L - COCA COLA",[10]],["REFRIGERANTE 1,5 L - GUARANÁ MINEIRO",[9]],["REFRIGERANTE 1,5 L - GUARANÁ MINEIRO ZERO",[9]],["REFRIGERANTE 2 L - COCA COLA",[16]],["REFRIGERANTE 2 L - GUARANÁ MINEIRO",[11]],["REFRIGERANTE MINEIRO 600ml",[7]],["REFRIGERANTE MINEIRO 350ml (LATA)",[5]]
    ]},
    {category:"Bordas Recheadas", items:[
      ["CATUPIRY - P",[12]],["CATUPIRY - M",[12]],["CATUPIRY - G",[12]],["CATUPIRY - F",[14]],["CHEDDAR - P",[12]],["CHEDDAR - M",[12]],["CHEDDAR - G",[12]],["CHEDDAR - F",[14]],["CATUPIRY C/ BACON - P",[14]],["CATUPIRY C/ BACON - M",[14]],["CATUPIRY C/ BACON - G",[14]],["CATUPIRY C/ BACON - F",[16]],["CHEDDAR C/ BACON - P",[14]],["CHEDDAR C/ BACON - M",[14]],["CHEDDAR C/ BACON - G",[14]],["CHEDDAR C/ BACON - F",[16]],["PRESUNTO C/ MUSSARELA - P",[16]],["PRESUNTO C/ MUSSARELA - M",[16]],["PRESUNTO C/ MUSSARELA - G",[16]],["PRESUNTO C/ MUSSARELA - F",[18]]
    ]}
  ];
  for(const group of menu){
    let {data:cat}=await supabase.from("categories").select("id").eq("user_id",user.id).eq("name",group.category).limit(1);
    let categoryId=cat?.[0]?.id;
    if(!categoryId){
      const {data:created}=await supabase.from("categories").insert({user_id:user.id,name:group.category,classification:"Receita"}).select("id").single();
      categoryId=created?.id;
    }
    if(!categoryId) continue;
    const names=group.items.map(x=>x[0]);
    const {data:existingProducts}=await supabase.from("products").select("name").eq("user_id",user.id).in("name",names);
    const existingNames=new Set((existingProducts||[]).map(x=>x.name));
    const missing=group.items.filter(x=>!existingNames.has(x[0])).map(([name,prices])=>({user_id:user.id,name,category_id:categoryId,sale_price:Number(prices[0]||0),cost_price:0,active:true}));
    if(missing.length) await supabase.from("products").insert(missing);
  }
}

function Login({onLogin}){
 const [email,setEmail]=useState(""),[password,setPassword]=useState(""),[loading,setLoading]=useState(false),[registering,setRegistering]=useState(false),[error,setError]=useState(""),[message,setMessage]=useState("");
 async function submit(e){e.preventDefault();setError("");setMessage("");setLoading(true);
  if(!supabase){setError("Supabase ainda não foi configurado.");setLoading(false);return}
  if(registering){const {data,error}=await supabase.auth.signUp({email,password});if(error)setError(error.message);else if(data.session){await seedUser(data.user);onLogin(data.user)}else setMessage("Cadastro realizado. Verifique seu e-mail para confirmar a conta.");}
  else {const {data,error}=await supabase.auth.signInWithPassword({email,password});if(error)setError(error.message);else{await seedUser(data.user);onLogin(data.user)}}
  setLoading(false);
 }
 return <div className="login-page"><div className="login-card"><div className="brand-mark">🍕</div><h1>Pizzaria Gestão</h1><p>Controle financeiro e operacional da sua pizzaria.</p>
  <form onSubmit={submit}><label>E-mail<input type="email" value={email} onChange={e=>setEmail(e.target.value)} required/></label><label>Senha<input type="password" minLength="6" value={password} onChange={e=>setPassword(e.target.value)} required/></label>{error&&<div className="error">{error}</div>}{message&&<div className="success">{message}</div>}<button className="primary" disabled={loading}>{loading?(registering?"Cadastrando...":"Entrando..."):(registering?"Criar conta":"Entrar")}</button></form>
  <button className="link-button" type="button" onClick={()=>{setRegistering(!registering);setError("");setMessage("")}}>{registering?"Já tenho uma conta — Entrar":"Ainda não tenho conta — Criar cadastro"}</button>
 </div></div>
}

function Dashboard({data}){
 const {sales,payables,receivables,bankTx}=data;
 const receita=sales.reduce((a,x)=>a+Number(x.net_amount||0),0), despesas=payables.filter(x=>x.status!=="paid").reduce((a,x)=>a+Number(x.amount||0),0);
 const aReceber=receivables.filter(x=>x.status!=="received").reduce((a,x)=>a+Number(x.amount||0)-Number(x.received_amount||0),0);
 const saldo=bankTx.reduce((a,x)=>a+(x.direction==="in"?Number(x.amount):-Number(x.amount)),0);
 return <main className="content"><div className="page-head"><div><h2>Dashboard</h2><p>Visão geral por competência — {new Date().toLocaleDateString("pt-BR",{month:"long",year:"numeric"})}.</p></div></div>
 <div className="cards"><div className="card"><span>Receita líquida</span><strong>{money(receita)}</strong><small>Vendas do período</small></div><div className="card"><span>Contas a pagar</span><strong>{money(despesas)}</strong><small>Pendências</small></div><div className="card"><span>A receber</span><strong>{money(aReceber)}</strong><small>Valores pendentes</small></div><div className="card"><span>Movimentação bancária</span><strong>{money(saldo)}</strong><small>Entradas menos saídas</small></div></div>
 <section className="panel"><div className="section-title"><h3>Resumo operacional</h3><button className="ghost" onClick={data.reload}><RefreshCw size={16}/>Atualizar</button></div>
 <div className="summary-grid"><div><b>{sales.length}</b><span>vendas</span></div><div><b>{payables.filter(x=>x.status==="pending").length}</b><span>contas pendentes</span></div><div><b>{receivables.filter(x=>x.status!=="received").length}</b><span>recebimentos pendentes</span></div><div><b>{bankTx.filter(x=>x.status==="unreconciled").length}</b><span>movimentos a conferir</span></div></div></section></main>
}

function Vendas({data}){
 const [open,setOpen]=useState(false),[saving,setSaving]=useState(false),[form,setForm]=useState({fact_date:today(),competence_date:today(),product_id:"",quantity:"1",delivery_fee:"0",discounts:"0",fees:"0",cancellations:"0",payment_method:"PIX",source:"manual",channel_id:""});
 const product=data.products.find(p=>p.id===form.product_id);
 const itemTotal=product?Number(product.sale_price||0)*Math.max(1,Number(form.quantity||1)):0;
 const gross=itemTotal+Number(form.delivery_fee||0),net=gross-Number(form.discounts||0)-Number(form.fees||0)-Number(form.cancellations||0);
 async function save(e){e.preventDefault();setSaving(true);try{const {data:sale,error}=await supabase.from("sales").insert({user_id:data.user.id,channel_id:form.channel_id||null,fact_date:new Date(form.fact_date+"T12:00:00").toISOString(),competence_date:form.competence_date,payment_method:form.payment_method,source:form.source,gross_amount:gross,delivery_fee:Number(form.delivery_fee||0),discounts:Number(form.discounts||0),fees:Number(form.fees||0),cancellations:Number(form.cancellations||0),net_amount:net}).select("id").single();if(error)throw error;
 if(product&&sale){const qty=Math.max(1,Number(form.quantity||1));const {error:itemError}=await supabase.from("sale_items").insert({sale_id:sale.id,product_name:product.name,quantity:qty,unit_price:Number(product.sale_price||0),total_amount:itemTotal});if(itemError)throw itemError}
 if(sale){const {error:e2}=await supabase.from("receivables").insert({user_id:data.user.id,sale_id:sale.id,description:`Venda ${form.payment_method||""}`.trim(),competence_date:form.competence_date,expected_date:form.competence_date,amount:net,received_amount:0,status:"pending",source:form.source||"manual"});if(e2)throw e2}
 setOpen(false);data.reload();}catch(error){alert(error?.message||"Não foi possível salvar a venda.")}finally{setSaving(false)}}
 return <main className="content"><div className="page-head"><div><h2>Vendas</h2><p>Registre a venda manual com produto, taxa de entrega e meio de recebimento.</p></div><button className="primary small" onClick={()=>setOpen(true)}><Plus size={16}/>Nova venda</button></div>
 <TableToolbar search={data.search} setSearch={data.setSearch} exportData={()=>downloadCSV(data.sales,"vendas.csv")}/>
 <div className="table-wrap"><table><thead><tr><th>Fato gerador</th><th>Competência</th><th>Produto vendido</th><th>Canal</th><th>Meio de recebimento</th><th>Entrega</th><th>Bruta</th><th>Taxas/descontos</th><th>Líquida</th></tr></thead><tbody>{data.sales.map(x=><tr key={x.id}><td>{new Date(x.fact_date).toLocaleDateString("pt-BR")}</td><td>{dateBR(x.competence_date)}</td><td>{x.sale_items?.[0]?.product_name||"—"}</td><td>{x.channels?.name||"—"}</td><td>{x.payment_method||"—"}</td><td>{money(x.delivery_fee)}</td><td>{money(x.gross_amount)}</td><td>{money(Number(x.discounts)+Number(x.fees)+Number(x.cancellations))}</td><td><b>{money(x.net_amount)}</b></td></tr>)}{!data.sales.length&&<EmptyRow text="Nenhuma venda registrada."/>}</tbody></table></div>
 {open&&<Modal title="Nova venda manual" onClose={()=>setOpen(false)}><form className="form-grid" onSubmit={save}>
 <Field label="Data da venda"><input type="date" value={form.fact_date} onChange={e=>setForm({...form,fact_date:e.target.value})}/></Field><Field label="Competência"><input type="date" value={form.competence_date} onChange={e=>setForm({...form,competence_date:e.target.value})}/></Field>
 <Field label="Produto vendido"><select value={form.product_id} onChange={e=>setForm({...form,product_id:e.target.value})}><option value="">Selecione no Cardápio</option>{data.products.map(x=><option key={x.id} value={x.id}>{x.name} — {money(x.sale_price)}</option>)}</select></Field>
 <Field label="Quantidade"><input type="number" min="1" step="1" value={form.quantity} onChange={e=>setForm({...form,quantity:e.target.value})}/></Field>
 <Field label="Canal"><select value={form.channel_id} onChange={e=>setForm({...form,channel_id:e.target.value})}><option value="">Selecione</option>{data.channels.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></Field>
 <Field label="Meio de recebimento"><select value={form.payment_method} onChange={e=>setForm({...form,payment_method:e.target.value})}><option>PIX</option><option>Dinheiro</option><option>Cartão de crédito</option><option>Cartão de débito</option><option>iFood</option><option>BeeFood</option><option>99Food</option><option>Outro</option></select></Field>
 <Field label="Taxa de entrega"><input type="number" step="0.01" value={form.delivery_fee} onChange={e=>setForm({...form,delivery_fee:e.target.value})}/></Field>
 <Field label="Descontos"><input type="number" step="0.01" value={form.discounts} onChange={e=>setForm({...form,discounts:e.target.value})}/></Field><Field label="Taxas"><input type="number" step="0.01" value={form.fees} onChange={e=>setForm({...form,fees:e.target.value})}/></Field><Field label="Cancelamentos"><input type="number" step="0.01" value={form.cancellations} onChange={e=>setForm({...form,cancellations:e.target.value})}/></Field>
 <div className="panel" style={{gridColumn:"1/-1"}}><b>Resumo:</b> Produto {money(itemTotal)} + entrega {money(form.delivery_fee)} = <b>{money(gross)}</b> • líquido {money(net)}</div>
 <div className="form-actions"><button className="primary" disabled={saving}>{saving?"Salvando...":"Salvar venda"}</button></div></form></Modal>}</main>
}

function Bancos({data}){
 const [open,setOpen]=useState(false),[form,setForm]=useState({fact_date:today(),competence_date:today(),description:"",classification:"Despesas",amount:"",direction:"out",bank_account_id:""});
 async function save(e){e.preventDefault();const {error}=await supabase.from("bank_transactions").insert({...form,user_id:data.user.id,amount:Number(form.amount),status:"unreconciled"});if(error)alert(error.message);else{setOpen(false);data.reload()}}
 return <main className="content"><div className="page-head"><div><h2>Bancos / Extratos</h2><p>Movimentos por data do fato gerador e competência.</p></div><button className="primary small" onClick={()=>setOpen(true)}><Plus size={16}/>Novo movimento</button></div>
 <div className="filters"><select value={data.bankFilter} onChange={e=>data.setBankFilter(e.target.value)}><option value="">Todos os bancos</option>{data.banks.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select><input placeholder="Pesquisar descrição..." value={data.search} onChange={e=>data.setSearch(e.target.value)}/><button className="ghost" onClick={()=>downloadCSV(data.bankTx,"extrato.csv")}><Download size={16}/>CSV</button></div>
 <div className="table-wrap"><table><thead><tr><th>Data</th><th>Descrição</th><th>Classificação</th><th>Categoria</th><th>Entrada</th><th>Saída</th><th>Banco</th><th>Status</th></tr></thead><tbody>{data.bankTx.map(x=><tr key={x.id}><td>{new Date(x.fact_date).toLocaleDateString("pt-BR")}</td><td>{x.description}</td><td>{x.classification}</td><td>{x.categories?.name||"—"}</td><td>{x.direction==="in"?money(x.amount):"—"}</td><td>{x.direction==="out"?money(x.amount):"—"}</td><td>{x.bank_accounts?.name||"—"}</td><td><span className="badge">{x.status==="reconciled"?"Conferido":"A conferir"}</span></td></tr>)}{!data.bankTx.length&&<EmptyRow text="Nenhum movimento registrado."/>}</tbody></table></div>
 {open&&<Modal title="Novo movimento bancário" onClose={()=>setOpen(false)}><form className="form-grid" onSubmit={async e=>{e.preventDefault();const {error}=await supabase.from("bank_transactions").insert({...form,user_id:data.user.id,amount:Number(form.amount)});if(error)alert(error.message);else{setOpen(false);data.reload()}}}><Field label="Data do fato gerador"><input type="date" value={form.fact_date} onChange={e=>setForm({...form,fact_date:e.target.value})}/></Field><Field label="Competência"><input type="date" value={form.competence_date} onChange={e=>setForm({...form,competence_date:e.target.value})}/></Field><Field label="Banco"><select value={form.bank_account_id} onChange={e=>setForm({...form,bank_account_id:e.target.value})} required><option value="">Selecione</option>{data.banks.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></Field><Field label="Descrição"><input value={form.description} onChange={e=>setForm({...form,description:e.target.value})} required/></Field><Field label="Classificação"><select value={form.classification} onChange={e=>setForm({...form,classification:e.target.value})}><option>Receita</option><option>Despesas</option><option>Outros</option></select></Field><Field label="Categoria"><select value={form.category_id||""} onChange={e=>setForm({...form,category_id:e.target.value})}><option value="">Selecione</option>{data.categories.filter(c=>c.classification===form.classification).map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></Field><Field label="Tipo"><select value={form.direction} onChange={e=>setForm({...form,direction:e.target.value})}><option value="out">Saída</option><option value="in">Entrada</option></select></Field><Field label="Valor"><input type="number" step="0.01" value={form.amount} onChange={e=>setForm({...form,amount:e.target.value})} required/></Field><div className="form-actions"><button className="primary">Salvar movimento</button></div></form></Modal>}</main>
}

function Contas({data}){
 const [open,setOpen]=useState(false),[form,setForm]=useState({description:"",amount:"",due_date:today(),competence_date:today(),category_id:"",supplier_id:"",payment_bank_account_id:"",status:"pending"});
 async function save(e){e.preventDefault();const {error}=await supabase.from("payables").insert({...form,user_id:data.user.id,category_id:form.category_id||null,supplier_id:form.supplier_id||null,payment_bank_account_id:form.payment_bank_account_id||null,amount:Number(form.amount)});if(error)alert(error.message);else{setOpen(false);data.reload()}}
 async function pay(x){const {error}=await supabase.from("payables").update({status:"paid",payment_date:today(),paid_bank_account_id:x.payment_bank_account_id}).eq("id",x.id);if(error)alert(error.message);else data.reload()}
 return <main className="content"><div className="page-head"><div><h2>Contas a pagar</h2><p>Ordenadas pela data de vencimento.</p></div><button className="primary small" onClick={()=>setOpen(true)}><Plus size={16}/>Nova conta</button></div>
 <div className="filters"><select value={data.payFilter} onChange={e=>data.setPayFilter(e.target.value)}><option value="">Todas</option><option value="pending">Pendentes</option><option value="paid">Pagas</option></select><input placeholder="Pesquisar..." value={data.search} onChange={e=>data.setSearch(e.target.value)}/></div>
 <div className="table-wrap"><table><thead><tr><th>Vencimento</th><th>Descrição</th><th>Fornecedor</th><th>Categoria</th><th>Competência</th><th>Valor</th><th>Status</th><th></th></tr></thead><tbody>{data.payables.map(x=><tr key={x.id}><td>{dateBR(x.due_date)}</td><td>{x.description}</td><td>{x.suppliers?.name||"—"}</td><td>{x.categories?.name||"—"}</td><td>{dateBR(x.competence_date)}</td><td>{money(x.amount)}</td><td><span className={x.status==="paid"?"badge ok":"badge"}>{x.status==="paid"?"Pago":"Pendente"}</span></td><td>{x.status!=="paid"&&<button className="icon-btn" title="Marcar como paga" onClick={()=>pay(x)}><CheckCircle2 size={18}/></button>}</td></tr>)}{!data.payables.length&&<EmptyRow text="Nenhuma conta cadastrada."/>}</tbody></table></div>
 {open&&<Modal title="Nova conta a pagar" onClose={()=>setOpen(false)}><form className="form-grid" onSubmit={save}><Field label="Descrição"><input value={form.description} onChange={e=>setForm({...form,description:e.target.value})} required/></Field><Field label="Valor"><input type="number" step="0.01" value={form.amount} onChange={e=>setForm({...form,amount:e.target.value})} required/></Field><Field label="Vencimento"><input type="date" value={form.due_date} onChange={e=>setForm({...form,due_date:e.target.value})}/></Field><Field label="Competência"><input type="date" value={form.competence_date} onChange={e=>setForm({...form,competence_date:e.target.value})}/></Field><Field label="Categoria"><select value={form.category_id} onChange={e=>setForm({...form,category_id:e.target.value})}><option value="">Selecione</option>{data.categories.filter(c=>c.classification==="Despesas").map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></Field><Field label="Fornecedor"><select value={form.supplier_id} onChange={e=>setForm({...form,supplier_id:e.target.value})}><option value="">Selecione</option>{data.suppliers.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></Field><Field label="Banco para pagamento"><select value={form.payment_bank_account_id} onChange={e=>setForm({...form,payment_bank_account_id:e.target.value})}><option value="">Selecione</option>{data.banks.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></Field><div className="form-actions"><button className="primary">Salvar conta</button></div></form></Modal>}</main>
}

function Cadastros({data}){
 const [tab,setTab]=useState("banks"),[name,setName]=useState("");
 async function add(table,extra={}){if(!name.trim())return;const {error}=await supabase.from(table).insert({user_id:data.user.id,name:name.trim(),...extra});if(error)alert(error.message);else{setName("");data.reload()}}
 return <main className="content"><div className="page-head"><div><h2>Configurações</h2><p>Cadastros básicos do sistema.</p></div></div><div className="tabs"><button className={tab==="banks"?"active":""} onClick={()=>setTab("banks")}>Bancos</button><button className={tab==="cards"?"active":""} onClick={()=>setTab("cards")}>Cartões</button><button className={tab==="cats"?"active":""} onClick={()=>setTab("cats")}>Categorias</button><button className={tab==="channels"?"active":""} onClick={()=>setTab("channels")}>Canais</button><button className={tab==="suppliers"?"active":""} onClick={()=>setTab("suppliers")}>Fornecedores</button></div><section className="panel"><div className="inline-form"><input placeholder="Nome do cadastro..." value={name} onChange={e=>setName(e.target.value)}/><button className="primary small" onClick={()=>add(tab==="banks"?"bank_accounts":tab==="cards"?"card_accounts":tab==="cats"?"categories":tab==="channels"?"channels":"suppliers",tab==="cats"?{classification:"Despesas"}:{})}><Plus size={16}/>Adicionar</button></div><div className="simple-list">{tab==="banks"&&data.banks.map(x=><div key={x.id}>{x.name}<span>{x.institution||""}</span></div>)}{tab==="cards"&&data.cards.map(x=><div key={x.id}>{x.name}<span>Fechamento {x.closing_day||"—"} / Vencimento {x.due_day||"—"}</span></div>)}{tab==="cats"&&data.categories.map(x=><div key={x.id}>{x.name}<span>{x.classification}</span></div>)}{tab==="channels"&&data.channels.map(x=><div key={x.id}>{x.name}</div>)}{tab==="suppliers"&&data.suppliers.map(x=><div key={x.id}>{x.name}<span>{x.phone||x.email||""}</span></div>)}</div></section></main>
}

function Recebimentos({data}){
 const [status,setStatus]=useState("");
 const rows=data.receivables.filter(x=>!status||x.status===status);
 async function receive(x){const bankId=window.prompt("ID do banco que recebeu (veja em Configurações):",data.banks[0]?.id||"");if(!bankId)return;const bank=data.banks.find(b=>b.id===bankId);if(!bank){alert("Banco não encontrado.");return}const {error}=await supabase.from("receivables").update({status:"received",received_date:today(),received_amount:Number(x.amount),bank_account_id:bank.id}).eq("id",x.id);if(error)alert(error.message);else data.reload()}
 return <main className="content"><div className="page-head"><div><h2>Recebimentos</h2><p>Controle o que foi gerado na competência e o que efetivamente entrou no banco.</p></div></div>
 <div className="filters"><select value={status} onChange={e=>setStatus(e.target.value)}><option value="">Todos</option><option value="pending">Pendentes</option><option value="received">Recebidos</option></select><button className="ghost" onClick={()=>downloadCSV(rows,"recebimentos.csv")}><Download size={16}/>CSV</button></div>
 <div className="table-wrap"><table><thead><tr><th>Competência</th><th>Descrição</th><th>Previsto</th><th>Recebido</th><th>Data prevista</th><th>Data real</th><th>Status</th><th></th></tr></thead><tbody>{rows.map(x=><tr key={x.id}><td>{dateBR(x.competence_date)}</td><td>{x.description}</td><td>{money(x.amount)}</td><td>{money(x.received_amount)}</td><td>{dateBR(x.expected_date)}</td><td>{dateBR(x.received_date)}</td><td><span className={x.status==="received"?"badge ok":"badge"}>{x.status==="received"?"Recebido":"Pendente"}</span></td><td>{x.status!=="received"&&<button className="icon-btn" onClick={()=>receive(x)} title="Marcar recebido"><CheckCircle2 size={18}/></button>}</td></tr>)}{!rows.length&&<EmptyRow text="Nenhum recebimento cadastrado."/>}</tbody></table></div></main>
}
function Cartoes({data}){const [open,setOpen]=useState(false),[form,setForm]=useState({card_account_id:"",fact_date:today(),competence_date:today(),description:"",category_id:"",total_amount:"",installments:"1"}),[rows,setRows]=useState([]);async function load(){const {data:d}=await supabase.from("card_transactions").select("*,card_accounts(name),categories(name)").eq("user_id",data.user.id).order("fact_date",{ascending:false}).limit(500);setRows(d||[])}useEffect(()=>{load()},[data.user.id]);async function save(e){e.preventDefault();const total=Number(form.total_amount||0),n=Math.max(1,Number(form.installments||1));const {data:t,error}=await supabase.from("card_transactions").insert({user_id:data.user.id,card_account_id:form.card_account_id,fact_date:form.fact_date,competence_date:form.competence_date,description:form.description,category_id:form.category_id||null,total_amount:total,installments:n,source:"manual"}).select("id").single();if(!error&&t){const base=Math.floor(total/n*100)/100;let acc=0;const card=data.cards.find(x=>x.id===form.card_account_id);for(let k=1;k<=n;k++){const amount=k===n?Number((total-acc).toFixed(2)):base;acc+=amount;const d=new Date(form.fact_date+"T12:00:00");d.setMonth(d.getMonth()+k-1);const due=new Date(d.getFullYear(),d.getMonth(),Number(card?.due_day||10));await supabase.from("card_installments").insert({card_transaction_id:t.id,installment_number:k,due_date:due.toISOString().slice(0,10),amount,status:"open"})}}if(error)alert(error.message);else{setOpen(false);load()}}return <main className="content"><div className="page-head"><div><h2>Cartões</h2><p>Compras e parcelas por competência, sem duplicar no pagamento da fatura.</p></div><button className="primary small" onClick={()=>setOpen(true)}><Plus size={16}/>Nova compra</button></div><div className="cards">{data.cards.map(c=><div className="card" key={c.id}><strong>{c.name}</strong><small>Fechamento: {c.closing_day||"—"} • Vencimento: {c.due_day||"—"}</small></div>)}</div><div className="table-wrap" style={{marginTop:20}}><table><thead><tr><th>Data</th><th>Descrição</th><th>Cartão</th><th>Categoria</th><th>Total</th><th>Parcelas</th></tr></thead><tbody>{rows.map(x=><tr key={x.id}><td>{dateBR(x.fact_date)}</td><td>{x.description}</td><td>{x.card_accounts?.name||"—"}</td><td>{x.categories?.name||"—"}</td><td>{money(x.total_amount)}</td><td>{x.installments}x</td></tr>)}{!rows.length&&<EmptyRow text="Nenhuma compra cadastrada."/>}</tbody></table></div>{open&&<Modal title="Nova compra no cartão" onClose={()=>setOpen(false)}><form className="form-grid" onSubmit={save}><Field label="Cartão"><select value={form.card_account_id} onChange={e=>setForm({...form,card_account_id:e.target.value})} required><option value="">Selecione</option>{data.cards.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></Field><Field label="Data da compra"><input type="date" value={form.fact_date} onChange={e=>setForm({...form,fact_date:e.target.value})}/></Field><Field label="Competência"><input type="date" value={form.competence_date} onChange={e=>setForm({...form,competence_date:e.target.value})}/></Field><Field label="Descrição"><input value={form.description} onChange={e=>setForm({...form,description:e.target.value})} required/></Field><Field label="Categoria"><select value={form.category_id} onChange={e=>setForm({...form,category_id:e.target.value})}><option value="">Selecione</option>{data.categories.filter(c=>c.classification==="Despesas").map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></Field><Field label="Valor total"><input type="number" step="0.01" value={form.total_amount} onChange={e=>setForm({...form,total_amount:e.target.value})} required/></Field><Field label="Parcelas"><input type="number" min="1" value={form.installments} onChange={e=>setForm({...form,installments:e.target.value})}/></Field><div className="form-actions"><button className="primary">Salvar compra</button></div></form></Modal>}</main>}
function Caixa({data}){const [bank,setBank]=useState(""),[from,setFrom]=useState(monthStart()),[to,setTo]=useState(today());const tx=data.bankTx.filter(x=>(!bank||x.bank_account_id===bank)&&(!from||x.fact_date>=from)&&(!to||x.fact_date<=to));const entradas=tx.filter(x=>x.direction==="in").reduce((a,x)=>a+Number(x.amount||0),0),saidas=tx.filter(x=>x.direction==="out").reduce((a,x)=>a+Number(x.amount||0),0);const previstos=data.receivables.filter(x=>x.status!=="received"&&(!from||x.expected_date>=from)&&(!to||x.expected_date<=to)).reduce((a,x)=>a+Number(x.amount||0),0);const pagar=data.payables.filter(x=>x.status!=="paid"&&(!from||x.due_date>=from)&&(!to||x.due_date<=to)).reduce((a,x)=>a+Number(x.amount||0),0);return <main className="content"><div className="page-head"><div><h2>Caixa / Fluxo de caixa</h2><p>Entradas e saídas pelo fato gerador, com visão do realizado e do previsto.</p></div><button className="ghost" onClick={()=>downloadCSV(tx,"fluxo-de-caixa.csv")}><Download size={16}/>CSV</button></div><div className="filters"><select value={bank} onChange={e=>setBank(e.target.value)}><option value="">Todos os bancos</option>{data.banks.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select><Field label="De"><input type="date" value={from} onChange={e=>setFrom(e.target.value)}/></Field><Field label="Até"><input type="date" value={to} onChange={e=>setTo(e.target.value)}/></Field></div><div className="cards"><div className="card"><span>Entradas realizadas</span><strong>{money(entradas)}</strong></div><div className="card"><span>Saídas realizadas</span><strong>{money(saidas)}</strong></div><div className="card"><span>Saldo do período</span><strong>{money(entradas-saidas)}</strong></div><div className="card"><span>Previsto ainda a receber</span><strong>{money(previstos)}</strong></div><div className="card"><span>Previsto a pagar</span><strong>{money(pagar)}</strong></div></div><section className="panel"><div className="section-title"><h3>Movimentações</h3><span>{tx.length} registro(s)</span></div><div className="table-wrap"><table><thead><tr><th>Data</th><th>Descrição</th><th>Banco</th><th>Classificação</th><th>Entrada</th><th>Saída</th><th>Status</th></tr></thead><tbody>{tx.map(x=><tr key={x.id}><td>{dateBR(x.fact_date)}</td><td>{x.description}</td><td>{x.bank_accounts?.name||"—"}</td><td>{x.classification}</td><td>{x.direction==="in"?money(x.amount):"—"}</td><td>{x.direction==="out"?money(x.amount):"—"}</td><td>{x.status==="reconciled"?"Conferido":"A conferir"}</td></tr>)}{!tx.length&&<EmptyRow text="Nenhuma movimentação no período."/>}</tbody></table></div></section></main>}

function Relatorios({data}){const totalIn=data.bankTx.filter(x=>x.direction==="in").reduce((a,x)=>a+Number(x.amount),0),totalOut=data.bankTx.filter(x=>x.direction==="out").reduce((a,x)=>a+Number(x.amount),0);return <main className="content"><div className="page-head"><div><h2>Relatórios</h2><p>Visão financeira consolidada.</p></div><button className="ghost" onClick={()=>downloadCSV(data.bankTx,"relatorio-financeiro.csv")}><Download size={16}/>Exportar CSV</button></div><div className="cards"><div className="card"><span>Entradas</span><strong>{money(totalIn)}</strong></div><div className="card"><span>Saídas</span><strong>{money(totalOut)}</strong></div><div className="card"><span>Resultado de caixa</span><strong>{money(totalIn-totalOut)}</strong></div><div className="card"><span>Vendas líquidas</span><strong>{money(data.sales.reduce((a,x)=>a+Number(x.net_amount||0),0))}</strong></div></div><section className="panel"><h3>Conferência</h3><p>Movimentos bancários não conciliados: <b>{data.bankTx.filter(x=>x.status==="unreconciled").length}</b>.</p><p>Contas a pagar pendentes: <b>{data.payables.filter(x=>x.status!=="paid").length}</b>.</p><p>Recebimentos pendentes: <b>{data.receivables.filter(x=>x.status!=="received").length}</b>.</p></section></main>}


function Compras({data}){
 const [open,setOpen]=useState(false),[form,setForm]=useState({description:"",amount:"",fact_date:today(),competence_date:today(),supplier_id:"",payment_bank_account_id:"",status:"pending"});
 async function save(e){e.preventDefault();const amount=Number(form.amount||0);const {error}=await supabase.from("purchases").insert({...form,user_id:data.user.id,amount,supplier_id:form.supplier_id||null,payment_bank_account_id:form.payment_bank_account_id||null});if(error)alert(error.message);else{setOpen(false);data.reload()}}
 const rows=data.purchases||[];
 return <main className="content"><div className="page-head"><div><h2>Compras / Matéria-prima</h2><p>Controle compras, fornecedor, competência e pagamento sem misturar com vendas.</p></div><button className="primary small" onClick={()=>setOpen(true)}><Plus size={16}/>Nova compra</button></div>
 <TableToolbar search={data.search} setSearch={data.setSearch} exportData={()=>downloadCSV(rows,"compras.csv")}/>
 <div className="table-wrap"><table><thead><tr><th>Data</th><th>Competência</th><th>Descrição</th><th>Fornecedor</th><th>Valor</th><th>Status</th></tr></thead><tbody>{rows.map(x=><tr key={x.id}><td>{dateBR(x.fact_date)}</td><td>{dateBR(x.competence_date)}</td><td>{x.description}</td><td>{x.suppliers?.name||"—"}</td><td>{money(x.amount)}</td><td>{x.status==="paid"?"Pago":"Pendente"}</td></tr>)}{!rows.length&&<EmptyRow text="Nenhuma compra registrada."/>}</tbody></table></div>
 {open&&<Modal title="Nova compra / matéria-prima" onClose={()=>setOpen(false)}><form className="form-grid" onSubmit={save}><Field label="Descrição"><input required value={form.description} onChange={e=>setForm({...form,description:e.target.value})}/></Field><Field label="Valor"><input required type="number" step="0.01" value={form.amount} onChange={e=>setForm({...form,amount:e.target.value})}/></Field><Field label="Data do fato"><input type="date" value={form.fact_date} onChange={e=>setForm({...form,fact_date:e.target.value})}/></Field><Field label="Competência"><input type="date" value={form.competence_date} onChange={e=>setForm({...form,competence_date:e.target.value})}/></Field><Field label="Fornecedor"><select value={form.supplier_id} onChange={e=>setForm({...form,supplier_id:e.target.value})}><option value="">Selecione</option>{data.suppliers.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></Field><Field label="Banco para pagamento"><select value={form.payment_bank_account_id} onChange={e=>setForm({...form,payment_bank_account_id:e.target.value})}><option value="">Ainda não pago</option>{data.banks.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></Field><div className="form-actions"><button className="primary">Salvar compra</button></div></form></Modal>}</main>
}

function Despesas({data}){
 const rows=(data.payables||[]).filter(x=>x.categories?.classification==="Despesas"||!x.categories);
 const total=rows.reduce((a,x)=>a+Number(x.amount||0),0),pending=rows.filter(x=>x.status!=="paid").reduce((a,x)=>a+Number(x.amount||0),0);
 return <main className="content"><div className="page-head"><div><h2>Despesas</h2><p>Despesas por competência, vencimento e status. Pagamento bancário permanece separado para evitar dupla contagem.</p></div><button className="ghost" onClick={()=>downloadCSV(rows,"despesas.csv")}><Download size={16}/>CSV</button></div><div className="cards"><div className="card"><span>Total lançado</span><strong>{money(total)}</strong></div><div className="card"><span>A pagar</span><strong>{money(pending)}</strong></div></div><div className="table-wrap"><table><thead><tr><th>Vencimento</th><th>Competência</th><th>Descrição</th><th>Categoria</th><th>Fornecedor</th><th>Valor</th><th>Status</th></tr></thead><tbody>{rows.map(x=><tr key={x.id}><td>{dateBR(x.due_date)}</td><td>{dateBR(x.competence_date)}</td><td>{x.description}</td><td>{x.categories?.name||"—"}</td><td>{x.suppliers?.name||"—"}</td><td>{money(x.amount)}</td><td>{x.status==="paid"?"Pago":"Pendente"}</td></tr>)}{!rows.length&&<EmptyRow text="Nenhuma despesa cadastrada."/>}</tbody></table></div></main>
}

function Cardapio({data}){
 const [open,setOpen]=useState(false),[editing,setEditing]=useState(null),[form,setForm]=useState({name:"",category_id:"",sale_price:"",cost_price:""});
 const rows=(data.products||[]).filter(x=>x.active!==false);
 const grouped=rows.reduce((acc,x)=>{const key=x.categories?.name||"Sem categoria";(acc[key]??=[]).push(x);return acc},{}); 
 function startNew(){setEditing(null);setForm({name:"",category_id:"",sale_price:"",cost_price:""});setOpen(true)}
 function startEdit(x){setEditing(x);setForm({name:x.name,category_id:x.category_id||"",sale_price:String(x.sale_price??""),cost_price:String(x.cost_price??"")});setOpen(true)}
 async function save(e){e.preventDefault();const payload={name:form.name.trim(),category_id:form.category_id||null,sale_price:Number(form.sale_price||0),cost_price:Number(form.cost_price||0),active:true};
   const q=editing?supabase.from("products").update(payload).eq("id",editing.id).eq("user_id",data.user.id):supabase.from("products").insert({...payload,user_id:data.user.id});
   const {error}=await q;if(error)alert(error.message);else{setOpen(false);data.reload()}
 }
 async function remove(x){if(!confirm("Excluir este item do cardápio? Ele será retirado da seleção de novas vendas, preservando o histórico."))return;const {error}=await supabase.from("products").update({active:false}).eq("id",x.id).eq("user_id",data.user.id);if(error)alert(error.message);else data.reload()}
 return <main className="content"><div className="page-head"><div><h2>Cardápio</h2><p>Produtos separados por tópico, prontos para seleção nas vendas manuais.</p></div><button className="primary small" onClick={startNew}><Plus size={16}/>Novo item</button></div>
 <div className="filters"><div className="search"><Search size={16}/><input placeholder="Pesquisar produto..." value={data.search} onChange={e=>data.setSearch(e.target.value)}/></div></div>
 {Object.entries(grouped).map(([category,items])=><section className="panel" key={category}><div className="section-title"><h3>{category}</h3><span>{items.length} item(ns)</span></div><div className="table-wrap"><table><thead><tr><th>Produto</th><th>Venda</th><th>Custo</th><th>Margem</th><th>Ações</th></tr></thead><tbody>{items.map(x=>{const margin=Number(x.sale_price||0)-Number(x.cost_price||0);return <tr key={x.id}><td>{x.name}</td><td>{money(x.sale_price)}</td><td>{money(x.cost_price)}</td><td>{money(margin)}</td><td><button className="icon-btn" title="Editar" onClick={()=>startEdit(x)}>✏️</button><button className="icon-btn" title="Excluir" onClick={()=>remove(x)}>🗑️</button></td></tr>})}</tbody></table></div></section>)}
 {!rows.length&&<section className="panel"><div className="empty-row">Nenhum item no cardápio.</div></section>}
 {open&&<Modal title={editing?"Editar item do cardápio":"Novo item do cardápio"} onClose={()=>setOpen(false)}><form className="form-grid" onSubmit={save}><Field label="Nome"><input required value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></Field><Field label="Categoria"><select value={form.category_id} onChange={e=>setForm({...form,category_id:e.target.value})}><option value="">Selecione</option>{data.categories.filter(x=>["Pizzas Tradicionais","Pizzas Especiais","Bebidas","Bordas Recheadas"].includes(x.name)).map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></Field><Field label="Preço de venda"><input type="number" step="0.01" value={form.sale_price} onChange={e=>setForm({...form,sale_price:e.target.value})}/></Field><Field label="Custo"><input type="number" step="0.01" value={form.cost_price} onChange={e=>setForm({...form,cost_price:e.target.value})}/></Field><div className="form-actions"><button className="primary">{editing?"Salvar alterações":"Salvar item"}</button></div></form></Modal>}</main>
}

function Conciliacao({data}){
 const pending=(data.bankTx||[]).filter(x=>x.status!=="reconciled");
 async function reconcile(tx,targetType,targetId,amount){const {error:e1}=await supabase.from("reconciliation_links").insert({user_id:data.user.id,bank_transaction_id:tx.id,target_type:targetType,target_id:targetId,matched_amount:amount});if(e1){alert(e1.message);return}const {error:e2}=await supabase.from("bank_transactions").update({status:"reconciled"}).eq("id",tx.id);if(e2)alert(e2.message);else data.reload()}
 const suggestion=tx=>{const list=tx.direction==="in"?data.receivables.filter(r=>r.status!=="received"):data.payables.filter(p=>p.status!=="paid");return list.find(r=>Math.abs(Number(r.amount)-Number(tx.amount))<0.01)};
 return <main className="content"><div className="page-head"><div><h2>Conciliação</h2><p>Relacione cada movimento bancário ao recebimento ou pagamento correspondente e evite dupla contagem.</p></div></div><div className="table-wrap"><table><thead><tr><th>Data</th><th>Descrição</th><th>Valor</th><th>Possível correspondência</th><th>Ação</th></tr></thead><tbody>{pending.map(tx=>{const s=suggestion(tx);return <tr key={tx.id}><td>{dateBR(tx.fact_date)}</td><td>{tx.description}</td><td>{money(tx.amount)}</td><td>{s?(s.description||"Registro")+" • "+money(s.amount):"Nenhuma automática"}</td><td>{s&&<button className="primary small" onClick={()=>reconcile(tx,tx.direction==="in"?"receivable":"payable",s.id,Math.min(Number(tx.amount),Number(s.amount)))}>Conferir</button>}</td></tr>})}{!pending.length&&<EmptyRow text="Tudo conciliado."/>}</tbody></table></div></main>
}

function normalizeHeader(v){return String(v??"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/[^a-z0-9]+/g," ").trim()}
function parseMoney(v){if(typeof v==="number")return v;const s=String(v??"").replace(/R\$|BRL/gi,"").replace(/\s/g,"").trim();if(!s)return 0;if(s.includes(",")&&s.includes("."))return Number(s.lastIndexOf(",")>s.lastIndexOf(".")?s.replace(/\./g,"").replace(",","."):s.replace(/,/g,""))||0;if(s.includes(","))return Number(s.replace(",", "."))||0;return Number(s)||0}
function parseExcelDate(v){if(v instanceof Date&&!Number.isNaN(v.getTime()))return v.toISOString().slice(0,10);if(typeof v==="number"){const d=new Date(Math.round((v-25569)*86400*1000));return Number.isNaN(d.getTime())?today():d.toISOString().slice(0,10)}const s=String(v??"").trim();if(!s)return today();if(/^\d{1,2}\/\d{1,2}\/\d{4}$/.test(s)){const [d,m,y]=s.split("/");return y+"-"+m.padStart(2,"0")+"-"+d.padStart(2,"0")}if(/^\d{4}-\d{2}-\d{2}/.test(s))return s.slice(0,10);const d=new Date(s);return Number.isNaN(d.getTime())?today():d.toISOString().slice(0,10)}
function headerIndex(headers,...names){const normalized=headers.map(normalizeHeader);for(const name of names){const i=normalized.indexOf(normalizeHeader(name));if(i>=0)return i}for(const name of names){const n=normalizeHeader(name);const i=normalized.findIndex(h=>h.includes(n)||n.includes(h));if(i>=0)return i}return -1}
function detectSource(headers){const h=headers.map(normalizeHeader).join(" ");if(/id completo do pedido|valor liquido|total pago pelo cliente/.test(h)&&/ifood/.test(h))return "ifood";if(/ref ifood|situacao delivery|valor pago/.test(h)&&/numero pedido/.test(h))return "beefood";if(/id da transacao|nome do titular|bandeira|metodo de captura/.test(h))return "cartao";if(/movimentacao|saldo antes|nosso numero/.test(h))return "banco_ton";if(/data da transacao|categoria/.test(h))return "banco_ifood";return "banco_ifood"}
